import React, { useEffect, useMemo, useRef, useState } from 'react';
import Icon, { Logo } from './Icons.jsx';
import { TYPES, STATUS, today, dateOffset, uid, recordValue, recordUnit, trainingVolume, filterRecords, derive, mutateRecord, setStatus } from './data.js';
import { loadState, saveState, exportData, validateImport } from './storage.js';
import RecordForm from './RecordForm.jsx';
import { Button, IconButton, Empty, SectionTitle, Field, Photo, Sheet, Sparkline, Status, formatDate, formatNumber, downloadJSON, FormError } from './ui.jsx';

const NAV=[['home','home','今日'],['log','book','训练志'],['calendar','calendar','日程'],['insights','chart','成长'],['gallery','images','相册']];
const TYPE_LABEL={plan:'训练计划',training:'力量训练',exercise:'动作库',body:'体重体脂',measure:'身体围度',meal:'饮食记录',water:'饮水记录',sleep:'睡眠恢复',record:'个人纪录'};
const DEFAULT_FILTER={q:'',type:'',status:'',tag:'',category:'',from:'',to:'',sort:'date-desc'};
const localDay=new Date(today()+'T12:00:00');
const dayLabel=localDay.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
const amountText=r=>`${formatNumber(recordValue(r))} ${recordUnit(r)||''}`;
const byNewest=(a,b)=>(b.date+b.time).localeCompare(a.date+a.time);
const byOldest=(a,b)=>(a.date+a.time).localeCompare(b.date+b.time);
const actionable=records=>records.filter(r=>!['exercise','record'].includes(r.type)&&!(r.type==='plan'&&records.some(x=>x.planId===r.id&&x.date===r.date)));
const selectRecords=(data,filters)=>filterRecords(filters.scope==='actions'?actionable(data.records):filters.scope==='consumed-water'?data.records.filter(r=>r.type==='water'&&r.status!=='planned'):data.records,filters);
const localTimestamp=value=>value?new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'';
function weekRange(){const d=new Date(today()+'T12:00:00');const offset=(d.getDay()+6)%7;return [dateOffset(-offset),today()]}
function useClock(){const [now,setNow]=useState(Date.now());useEffect(()=>{const i=setInterval(()=>setNow(Date.now()),500);return()=>clearInterval(i)},[]);return now;}

export default function App(){
 const [data,setData]=useState(null),[loadError,setLoadError]=useState(''),[page,setPage]=useState('home'),[modal,setModal]=useState(null),[viewer,setViewer]=useState(null),[toast,setToast]=useState(null),[filters,setFilters]=useState(DEFAULT_FILTER),[busy,setBusy]=useState(false),[achievement,setAchievement]=useState(null),[day,setDay]=useState(today()),[calendarMonth,setCalendarMonth]=useState(today().slice(0,7)),[galleryTheme,setGalleryTheme]=useState('all'),[range,setRange]=useState('week'),[customRange,setCustomRange]=useState({from:dateOffset(-29),to:today()});
 const dataRef=useRef(null),scroller=useRef(null),toastTimeout=useRef(null),saveLock=useRef(false),fileInput=useRef(null);
 const [timer,setTimer]=useState(()=>{try{return JSON.parse(localStorage.getItem('jidong-timer')||'null')}catch{return null}});
 const now=useClock();
 const remaining=timer?Math.max(0,Math.ceil((timer.running?timer.deadline-now:timer.remaining*1000)/1000)):90;
 useEffect(()=>{loadState().then(s=>{setData(s);dataRef.current=s}).catch(e=>{console.error('肌动：本地训练档案读取失败',e);setLoadError(e.message)})},[]);
 useEffect(()=>{if(timer?.running&&remaining===0){setTimer(t=>({...t,running:false,remaining:0}));notify('休息结束，下一组准备好了。');if(navigator.vibrate)navigator.vibrate([70,50,70]);}},[remaining]);
 useEffect(()=>{try{timer?localStorage.setItem('jidong-timer',JSON.stringify(timer)):localStorage.removeItem('jidong-timer')}catch(e){console.error('肌动：计时状态保存失败',e)}},[timer]);
 useEffect(()=>()=>clearTimeout(toastTimeout.current),[]);
 function notify(message,action){clearTimeout(toastTimeout.current);setToast({message,action});toastTimeout.current=setTimeout(()=>setToast(null),action?8000:3800)}
 async function commit(next,message='这一笔，已经留在训练志里。',opts={}){if(saveLock.current){notify('正在保存上一笔，请稍候。');return false}saveLock.current=true;setBusy(true);const previous=dataRef.current;try{await saveState(next,opts);dataRef.current=next;setData(next);if(message)notify(message,opts.undo?{label:'撤销',run:()=>commit(previous,'已经恢复，这一笔仍在。')}:undefined);return true}catch(e){console.error('肌动：保存训练档案失败',e);notify(`这次还没存上：${e.message||'本地存储暂不可用'}。请重试。`);return false}finally{saveLock.current=false;setBusy(false)}}
 function navigate(next){setPage(next);setModal(null);scroller.current?.scrollTo({top:0,behavior:'instant'})}
 function openLog(extra={}){setFilters({...DEFAULT_FILTER,...extra});navigate('log')}
 function newRecord(type='training',date=today(),initialTemplate){setModal({type:'form',initialType:type,initialDate:date,initialTemplate})}
 function detail(id){setModal({type:'detail',id})}
 function openMedia(id){const media=dataRef.current.media.find(m=>m.id===id);if(media)setViewer(media);else notify('这张素材已移走，可以从详情重新添加。')}
 function coverOf(record){return data.media.find(m=>m.id===record.coverId)||data.media.find(m=>record.mediaIds?.includes(m.id))}
 async function saveRecord(record,media=[]){const merged={...dataRef.current,media:[...dataRef.current.media,...media.filter(m=>!dataRef.current.media.some(x=>x.id===m.id))]};const previous=dataRef.current.records.find(r=>r.id===record.id);let next=mutateRecord(merged,record,'save');if(record.type==='plan'&&previous&&previous.status!==record.status)next=setStatus(next,record.id,record.status);const ok=await commit(next,'记录已入册，日程和成长数据也已更新。',{undo:true});if(ok){setModal({type:'detail',id:record.id});if(record.status==='done'&&previous?.status!=='done'){const result=derive(next);setAchievement({recordId:record.id,title:record.type==='training'?'这一练，有分量。':'又收好一份成长证据。',text:record.type==='training'?`${formatNumber(trainingVolume(record))} kg 训练量已计入 · 累计 ${result.trainingCount} 次训练`:`「${record.title}」已入册，今日进度和日程已经更新。`,badge:record.type==='training'?'力量留痕':'今日印记'});}}else throw new Error('保存未完成，请保留当前内容后重试。');}
 async function changeStatus(record,status){const before=derive(dataRef.current);const next=setStatus(dataRef.current,record.id,status);const ok=await commit(next,status==='done'?'又留下一份努力的证据。':'状态已更新，按自己的节奏来。',{undo:true});if(ok&&status==='done'){const after=derive(next);setAchievement({recordId:record.id,title:record.type==='training'?'这一练，有分量。':'今天，又向前一步。',text:record.type==='training'?`${formatNumber(trainingVolume(next.records.find(x=>x.id===record.id)))} kg 训练量已计入 · 累计 ${after.trainingCount} 次训练`:`「${record.title}」已完成，今日进度同步更新。`,badge:record.type==='training'?'力量留痕':'今日印记',newMilestone:after.trainingCount>=5&&before.trainingCount<5});}}
 function requestComplete(record){if(record.type==='training'&&record.fields.exercises?.some(e=>e.sets.some(s=>!s.done))){setModal({type:'complete',id:record.id})}else changeStatus(record,'done')}
 async function startTraining(plan){if(!plan.fields.exercises?.length){if(plan.status!=='active'){if(!await commit(setStatus(dataRef.current,plan.id,'active'),'恢复安排已经开始，今天也给身体一点余地。'))return}detail(plan.id);return}const active=data.records.find(r=>r.type==='training'&&r.planId===plan.id&&r.status==='active');if(active){detail(active.id);return}const r={...structuredClone(plan),id:uid(),type:'training',title:plan.title+' · 执行',status:'active',date:today(),time:new Date().toTimeString().slice(0,5),planId:plan.id,fields:{...structuredClone(plan.fields),exercises:(plan.fields.exercises||[]).map(e=>({...e,sets:e.sets.map(s=>({...s,done:false}))}))}};const ok=await commit(mutateRecord(dataRef.current,r),'训练已开始。把每一组稳稳记下来。');if(ok)detail(r.id)}
 async function quickWater(){const r={id:uid(),type:'water',title:'训练间隙 · 补水 250 ml',date:today(),time:new Date().toTimeString().slice(0,5),status:'done',category:'补水',tags:['随手记录'],notes:'在训练间隙喝了一杯水。',coverId:'media-water',mediaIds:['media-water'],fields:{amount:250}};await commit(mutateRecord(dataRef.current,r),'喝下的 250 ml，已计入今天的补水。',{undo:true})}
 function startTimer(recordId){setTimer(t=>t?{...t,recordId:recordId||t.recordId||null}:{duration:90,remaining:90,running:false,recordId:recordId||null});setModal({type:'timer',id:recordId})}
 async function replaceCover(recordId,mediaId){const r=dataRef.current.records.find(r=>r.id===recordId);if(!r)return;await commit(mutateRecord(dataRef.current,{...r,coverId:mediaId,mediaIds:[...new Set([...(r.mediaIds||[]),mediaId])]}),'新的封面，已经同步到训练志与日程。',{undo:true})}
 async function removeRecord(record){const next=mutateRecord(dataRef.current,record,'delete');if(await commit(next,'这一页已移出训练志，相关数字已重新计算。',{undo:true})){setModal(null);if(viewer&&!next.records.some(r=>r.mediaIds?.includes(viewer.id)))setViewer(null)}}
 async function restoreFile(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;try{if(file.size>80*1024*1024)throw new Error('备份超过 80 MB');const raw=JSON.parse(await file.text());const valid=validateImport(raw);setModal({type:'import',state:valid,filename:file.name})}catch(e){console.error('肌动：备份读取失败',e);notify('这份备份还不能读取：'+e.message)}}
 if(!data)return <div className="app-shell boot"><Logo size={58}/><h1>肌动</h1><p>{loadError?'训练档案暂时没能打开':'正在翻开你的训练日志…'}</p>{loadError?<><p className="form-error">{loadError}</p><Button onClick={()=>location.reload()}>重新读取</Button><Button variant="secondary" onClick={()=>fileInput.current.click()}>选择本地备份恢复</Button><input hidden ref={fileInput} type="file" accept=".json" onChange={async e=>{try{const s=validateImport(JSON.parse(await e.target.files[0].text()));await saveState(s,{replaceCorrupt:true});setData(s);dataRef.current=s;setLoadError('')}catch(err){setLoadError(err.message)}}}/></>:<div className="loading-track"><i/></div>}</div>;
 const summary=derive(data);
 const actionRecords=summary.today.records;
 const doneToday=summary.today.done,completion=summary.today.completion;
 const focus=data.records.find(r=>r.type==='plan'&&r.date===today()&&r.status!=='done')||data.records.find(r=>r.type==='training'&&r.date===today()&&r.status!=='done')||data.records.filter(r=>r.type==='plan'&&r.status!=='done').sort(byOldest)[0];
 const recent=data.records.find(r=>r.id===summary.recentActivities[0]?.recordId)||[...data.records].filter(r=>!['exercise','plan'].includes(r.type)&&r.status==='done').sort(byNewest)[0];
 const bodies=data.records.filter(r=>r.type==='body'&&r.status==='done').sort(byOldest),latestBody=bodies.at(-1);
 const [weekStart,weekEnd]=weekRange(),weekly=derive(data,weekStart,weekEnd);
 const filtered=selectRecords(data,filters);
 const currentRecord=modal?.id?data.records.find(r=>r.id===modal.id):null;
 const actions={detail,openMedia,coverOf,newRecord,startTraining,startTimer,changeStatus,requestComplete,edit:r=>setModal({type:'form',record:r}),remove:r=>setModal({type:'delete',id:r.id}),commit,notify,saveRecord,openLog};
 const pageHeads={log:['训练志','每一次，都有迹可循。'],calendar:['训练日程','给努力，也给恢复留出位置。'],insights:['身体在回答','变化，会被好好看见。'],gallery:['身体档案室','那些看得见的进步。'],settings:['我的训练方式','找到适合自己的节奏。']};
 return <div className="app-shell">
  <main className="app-scroll" ref={scroller} key={page}>
   {page==='home'?<>
    <header className="brand-header"><button className="brand" onClick={()=>navigate('home')} aria-label="肌动首页"><Logo size={38}/><div><strong>肌动<span>JIDONG</span></strong><small>身体成长工作台</small></div></button><button className="avatar" onClick={()=>navigate('settings')} aria-label="个人设置">{data.settings.name?.slice(-1)||'屿'}<i/></button></header>
    <div className="home-greeting"><div className="eyebrow">{dayLabel}<span> / </span> 训练手记</div><h1>把今天，练成进步<span>。</span></h1><button className="day-tag" onClick={()=>{setDay(today());navigate('calendar')}}><i/> {completion===100?'今日已收工':'今天继续'}<Icon name="chevron" size={13}/></button></div>
    <section className="hero-card">
      <Photo src="/assets/hero.png" alt="肌动训练手账：肩背肌群解剖海报、哑铃和网格训练日志" onClick={()=>openMedia('media-hero')} className="hero-photo"/>
      <div className="hero-top"><span className="small-label">训练日志 <b>NO. {String(data.records.filter(r=>r.type==='training').length+(data.records.some(r=>r.type==='training'&&r.date===today())?0:1)).padStart(2,'0')}</b></span><span className="hero-stamp">肌群档案<br/><b>MOVEMENT</b></span></div>
      <div className="hero-copy"><span className="orange-kicker">TODAY'S FOCUS</span><h2>{focus?focus.title.split(/[·｜]/)[0].trim():'今天，也为自己留一点时间'}</h2><p>{focus?`${focus.fields.exercises?.length||3} 个动作 · ${focus.fields.duration||45} 分钟`:'一份新计划，从这里开始'}</p><div className="muscle-tags">{(focus?.tags?.slice(0,3)||['力量','节奏','成长']).map(t=><span key={t}>{t}</span>)}</div></div>
      <div className="hero-axis"><i/> 用动作书写身体</div>
      <div className="hero-bottom"><div className="hero-session"><span><Icon name="dumbbell" size={16}/> {focus?.fields.location||'社区训练馆'}</span><span>{focus?.time||'随时开始'} <span className="soft">/ 今日主练</span></span></div><Button icon="play" onClick={()=>focus?(focus.type==='plan'?startTraining(focus):detail(focus.id)):newRecord('plan')}>{focus?(data.records.some(r=>r.type==='training'&&r.planId===focus.id&&r.status==='active')||focus.type==='training'?'继续今日训练':'开始今日训练'):'安排一次训练'}<Icon name="arrow" size={19}/></Button></div>
    </section>
    <div className="home-metrics"><button className="volume-metric" onClick={()=>openLog({type:'training',status:'done',from:weekStart,to:weekEnd})}><span className="metric-caption">本周 · 累计训练量<Icon name="arrow" size={14}/></span><div><b>{formatNumber(weekly.trainingVolume)}</b><small>kg</small></div><p>{weekly.trainingCount}/{data.settings.weeklyTrainingGoal} 次周目标 · 连续 {summary.trainingStreak} 天</p></button><button className="weight-metric" onClick={()=>latestBody?detail(latestBody.id):newRecord('body')}><span className="metric-caption">晨起体重 <Icon name="arrow" size={14}/></span><div><b>{latestBody?.fields.weight??'—'}</b><small>kg</small></div><Sparkline values={bodies.slice(-6).map(r=>r.fields.weight)} width={126} height={30}/><p>{bodies.length>1?`${formatDate(bodies[0].date,true)} — ${formatDate(latestBody.date,true)}`:'记下身体的起点'}</p></button></div>
    <SectionTitle title="今天，专注这几件" aside={`${doneToday}/${actionRecords.length} 已完成`} onClick={()=>openLog({from:today(),to:today(),scope:'actions'})}/>
    <button className="daily-progress" onClick={()=>openLog({from:today(),to:today(),scope:'actions'})} aria-label={`今日完成率 ${completion}%`}><span style={{width:`${completion}%`}}/></button>
    <div className="today-tasks">{actionRecords.filter(r=>r.status!=='done').sort((a,b)=>(['plan','training'].includes(a.type)?0:1)-(['plan','training'].includes(b.type)?0:1)||byOldest(a,b)).slice(0,3).map((r,i)=><div className="task-row" key={r.id}><button className="task-mark" onClick={()=>r.type==='plan'?startTraining(r):r.type==='training'?detail(r.id):requestComplete(r)} aria-label={`${['plan','training'].includes(r.type)?'开始':'完成'}${r.title}`}><Icon name={['plan','training'].includes(r.type)?'play':r.type==='water'?'water':'check'} size={19}/></button><button className="task-text" onClick={()=>detail(r.id)}><span>{r.title}</span><small>{r.time} · {TYPE_LABEL[r.type]}{i===0?' · 今日优先':''}</small></button><span className={`priority ${i===0?'first':''}`}>{i===0?'优先':'待记录'}</span></div>)}{!actionRecords.some(r=>r.status!=='done')&&<Empty title="今天的努力，已经收好" text="恢复也是成长的一部分，明天继续。" action="安排下一次" onAction={()=>newRecord('plan',dateOffset(1))}/>}</div>
    <SectionTitle title="随手留一笔" aside="小习惯，大变化"/>
    <div className="quick-actions">{[['water','+250 ml',quickWater],['body','记录体测',()=>newRecord('body')],['meal','记一餐',()=>newRecord('meal')],['clock','休息计时',()=>startTimer()]].map(([icon,label,fn])=><button key={icon} onClick={fn} disabled={busy}><Icon name={icon} size={24}/><span>{label}</span></button>)}</div>
    <div className="hydration-note"><Photo src="/assets/water.png" alt="随身补水瓶细节" onClick={()=>openMedia('media-water')}/><button onClick={()=>openLog({type:'water',from:today(),to:today(),scope:'consumed-water'})}><span>今日补水 <b>{formatNumber(summary.waterToday)}<small> / {formatNumber(summary.waterGoal)} ml</small></b></span><div><i style={{width:`${Math.min(100,summary.waterToday/summary.waterGoal*100)}%`}}/></div><p>{summary.waterToday>=summary.waterGoal?'今天的补水目标，已经留下证据':`距离自己的目标，还差 ${formatNumber(summary.waterGoal-summary.waterToday)} ml`}</p></button></div>
    <SectionTitle title="最近一页" aside="翻开训练志" onClick={()=>openLog()}/>{recent?<RecordCard record={recent} {...actions} feature/>:<Empty onAction={()=>newRecord()}/>}
    <SectionTitle title="努力，有回声" aside="全部成果" onClick={()=>navigate('insights')}/>
    <button className="achievement-card" onClick={()=>setModal({type:'report'})}><div className="medal"><Icon name="trophy" size={31}/><span>JIDONG</span></div><div><span className="small-label">第一个里程碑</span><h3>{summary.trainingCount>=5?'五次出勤，力量初成。':`再练 ${Math.max(0,5-summary.trainingCount)} 次，点亮力量印记`}</h3><p>每一次出现，都算数。<Icon name="arrow" size={16}/></p></div></button>
    <ActivityList data={data} detail={detail}/><p className="brand-quote">强壮不是口号，<br/>是每一次训练留下的证据。</p>
   </>:<>
    <header className="page-heading"><div className="eyebrow">JIDONG / {page==='settings'?'PERSONAL':'TRAINING JOURNAL'}</div><div className="page-title-row"><h1>{pageHeads[page][0]}</h1>{page==='settings'?<IconButton name="back" label="返回今日" onClick={()=>navigate('home')}/>:<button className="mini-brand" onClick={()=>navigate('settings')} aria-label="个人设置"><Logo size={29}/></button>}</div><p>{pageHeads[page][1]}</p></header>
    {page==='log'&&<>
     <div className="log-toolbar"><div className="search-row"><div className="search-box"><Icon name="search" size={19}/><input aria-label="搜索训练志" placeholder="搜动作、记录、标签…" value={filters.q} onChange={e=>setFilters({...filters,q:e.target.value})}/>{filters.q&&<button aria-label="清除搜索" onClick={()=>setFilters({...filters,q:''})}><Icon name="close" size={16}/></button>}</div><IconButton name="filter" label="筛选与排序" onClick={()=>setModal({type:'filter'})}/></div><div className="chip-scroll">{[['','全部'],['training','训练'],['plan','计划'],['exercise','动作库'],['body','体测'],['measure','围度'],['meal','饮食'],['water','饮水'],['sleep','睡眠'],['record','纪录']].map(([v,t])=><button key={v} className={`chip ${filters.type===v?'active':''}`} onClick={()=>setFilters({...filters,type:v})}>{t}</button>)}</div></div>
     <div className="list-summary"><span>{filtered.length} 条{filters.scope==='actions'?'行动 · 已合并计划与执行':'身体成长记录'}</span><button onClick={()=>setModal({type:'filter'})}><Icon name="sort" size={14}/>{filters.sort==='date-desc'?'最新在前':filters.sort==='date-asc'?'最早在前':filters.sort==='value-desc'?'数值从高到低':'数值从低到高'}</button></div>
     {(filters.status||filters.category||filters.tag||filters.from||filters.to)&&<div className="active-filters"><span>{[filters.status&&STATUS[filters.status],filters.category,filters.tag,filters.from&&formatDate(filters.from,true),filters.to&&'至 '+formatDate(filters.to,true)].filter(Boolean).join(' · ')}</span><button onClick={()=>setFilters({...DEFAULT_FILTER,q:filters.q,type:filters.type})}>清除</button></div>}
     <div className="records-list">{filtered.map(r=><RecordCard key={r.id} record={r} {...actions}/>)}</div>{!filtered.length&&<Empty title={data.records.length?'这一页，还没有匹配的记录':'你的训练志，等你落笔'} text={data.records.length?'换个关键词，或者把筛选条件放宽一点。':'第一组训练、第一餐或今天的体重，都值得记下来。'} action={data.records.length?'清除全部筛选':'新增记录'} onAction={()=>data.records.length?setFilters(DEFAULT_FILTER):newRecord()}/>}
     <button className="back-top" onClick={()=>scroller.current.scrollTo({top:0,behavior:'smooth'})}>↑ 回到顶部</button>
    </>}
    {page==='calendar'&&<CalendarPage data={data} day={day} setDay={setDay} month={calendarMonth} setMonth={setCalendarMonth} actions={actions}/>}
    {page==='insights'&&<Insights data={data} range={range} setRange={setRange} customRange={customRange} setCustomRange={setCustomRange} actions={actions} report={dates=>setModal({type:'report',...dates})}/>}
    {page==='gallery'&&<Gallery data={data} theme={galleryTheme} setTheme={setGalleryTheme} actions={actions} upload={()=>setModal({type:'upload'})}/>}
    {page==='settings'&&<Settings data={data} commit={commit} notify={notify} exportAll={()=>{exportData(data);notify('训练档案已打包，请在下载中保存。')}} importAll={()=>fileInput.current.click()}/>}
   </>}
   <div className="bottom-spacer"/>
  </main>
  {timer&&modal?.type!=='timer'&&<button className="timer-mini" onClick={()=>setModal({type:'timer'})}><Icon name="clock" size={16}/><b>{String(Math.floor(remaining/60)).padStart(2,'0')}:{String(remaining%60).padStart(2,'0')}</b><span>{remaining===0?'开始下一组':timer.running?'休息中':'已暂停'}</span></button>}
  {page==='log'&&!modal&&<button className="floating-add" onClick={()=>newRecord(filters.type||'training')} aria-label="新增记录"><Icon name="plus" size={25}/></button>}
  <nav className="bottom-nav" aria-label="主导航">{NAV.map(([id,icon,label])=><button key={id} className={page===id?'active':''} onClick={()=>navigate(id)} aria-current={page===id?'page':undefined}><Icon name={icon} size={23}/><span>{label}</span>{page===id&&<i/>}</button>)}</nav>
  <input hidden type="file" accept=".json" ref={fileInput} onChange={restoreFile}/>
  {modal?.type==='form'&&<RecordForm record={modal.record} initialType={modal.initialType} initialDate={modal.initialDate} initialTemplate={modal.initialTemplate} data={data} onSave={saveRecord} onClose={()=>setModal(modal.record?{type:'detail',id:modal.record.id}:null)}/>}
  {modal?.type==='detail'&&currentRecord&&<Detail key={currentRecord.id} record={currentRecord} data={data} actions={actions} close={()=>setModal(null)} busy={busy}/>}
  {modal?.type==='filter'&&<FilterSheet filters={filters} data={data} close={()=>setModal(null)} apply={f=>{setFilters(f);setModal(null);notify('训练志已经按你的条件整理好。')}}/>}
  {modal?.type==='timer'&&<Sheet title="组间休息" subtitle="让呼吸回来，再稳稳完成下一组。" onClose={()=>setModal(null)} footer={<Button variant="secondary" onClick={()=>{setTimer(null);setModal(null);notify('计时已结束，按身体的节奏继续。')}}>结束计时</Button>}><div className="timer-dial"><Icon name="clock" size={25}/><strong>{String(Math.floor(remaining/60)).padStart(2,'0')}<em>:</em>{String(remaining%60).padStart(2,'0')}</strong><span>{remaining===0?'休息结束 · 下一组，准备好':'组间恢复 / REST'}</span></div><div className="timer-presets">{[30,60,90,120].map(s=><button key={s} className={timer?.duration===s?'active':''} onClick={()=>setTimer({duration:s,remaining:s,running:false,recordId:modal.id||timer?.recordId})}>{s} 秒</button>)}</div><div className="two-buttons"><Button icon={timer?.running?'pause':'play'} onClick={()=>{const base=timer||{duration:90,remaining:90,recordId:modal.id};setTimer({...base,remaining:remaining||base.duration,running:!base.running,deadline:Date.now()+(remaining||base.duration)*1000})}}>{timer?.running?'暂停':remaining===0?'再计一组':'开始计时'}</Button><Button variant="secondary" icon="reset" onClick={()=>setTimer(t=>({...t,running:false,remaining:t?.duration||90}))}>重置</Button></div>{timer?.recordId&&data.records.some(r=>r.id===timer.recordId)&&<button className="source-link" onClick={()=>detail(timer.recordId)}>返回本次训练 <Icon name="arrow" size={17}/></button>}<p className="help-note">切换页面或刷新后仍按截止时间计时。页面关闭时不发送系统通知。</p></Sheet>}
  {modal?.type==='delete'&&currentRecord&&<Sheet title="要把这一页移出训练志吗？" onClose={()=>detail(currentRecord.id)} footer={<><Button variant="danger" icon="trash" disabled={busy} onClick={()=>removeRecord(currentRecord)}>确认删除这条记录</Button><Button variant="secondary" onClick={()=>detail(currentRecord.id)}>留在训练志里</Button></>}><div className="delete-preview"><Icon name="book" size={30}/><h3>{currentRecord.title}</h3><p>{formatDate(currentRecord.date)} · {TYPE_LABEL[currentRecord.type]}</p></div><p>删除后，首页进度、日程、统计与对应成就会重新计算。</p><p>关联的 {data.records.filter(r=>r.planId===currentRecord.id||r.id===currentRecord.planId).length} 条计划 / 执行记录会保留并解除关联。仅属于这条记录的素材会从相册移除；其他记录正在使用的素材会保留。</p><p className="help-note">删除后 8 秒内，可在提示中撤销。</p></Sheet>}
  {modal?.type==='complete'&&currentRecord&&<Sheet title="这一练，准备收工了吗？" onClose={()=>detail(currentRecord.id)} footer={<><Button onClick={async()=>{const r={...currentRecord,fields:{...currentRecord.fields,exercises:currentRecord.fields.exercises.map(e=>({...e,sets:e.sets.map(s=>({...s,done:true}))}))}};const next=mutateRecord(dataRef.current,r);if(await commit(next,null)){setModal({type:'detail',id:r.id});changeStatus(r,'done')}}}>已全部练完，标记全部组并完成</Button><Button variant="secondary" onClick={()=>{changeStatus(currentRecord,'done');detail(currentRecord.id)}}>结束训练，仅计已勾选组</Button><button className="text-button" onClick={()=>detail(currentRecord.id)}>继续记录</button></>}><p>还有 {currentRecord.fields.exercises.flatMap(e=>e.sets).filter(s=>!s.done).length} 组未勾选。训练量只计算实际完成的组，不会把计划重量算成成绩。</p></Sheet>}
  {modal?.type==='report'&&<Report data={data} from={modal.from} to={modal.to} actions={actions} close={()=>setModal(null)} notify={notify}/>}
  {modal?.type==='upload'&&<UploadSheet data={data} onClose={()=>setModal(null)} onChoose={id=>{const r=data.records.find(r=>r.id===id);setModal({type:'form',record:r});notify('在第 3 步添加素材，图片会跟这条记录一起保存。')}} newRecord={()=>newRecord('training')}/>}
  {modal?.type==='import'&&<Sheet title="用备份恢复训练档案？" onClose={()=>setModal(null)} footer={<><Button onClick={async()=>{if(await commit(modal.state,'备份已恢复，所有页面已同步。',{replaceCorrupt:true,undo:true})){setModal(null);navigate('home')}}}>确认用备份替换本地数据</Button><Button variant="secondary" onClick={()=>setModal(null)}>保留当前档案</Button></>}><p>「{modal.filename}」包含 {modal.state.records.length} 条记录。恢复会覆盖当前 {data.records.length} 条记录、图片和个人设置。</p><Button variant="secondary" icon="download" onClick={()=>exportData(data)}>先导出当前档案</Button><p className="help-note">恢复后 8 秒内可以撤销。</p></Sheet>}
  {viewer&&<MediaViewer media={viewer} data={data} close={()=>setViewer(null)} detail={id=>{setViewer(null);detail(id)}} replaceCover={replaceCover}/>}
  {achievement&&<div className="achievement-scrim" onClick={e=>e.target===e.currentTarget&&setAchievement(null)}><section className="achievement-feedback" role="dialog" aria-label="完成反馈"><span className="completed-stamp">{achievement.newMilestone?'力量初成':achievement.badge}</span><div className="big-medal"><Icon name="trophy" size={53}/></div><span className="orange-kicker">EFFORT, RECORDED.</span><h2>{achievement.title}</h2><p>{achievement.text}</p><Button onClick={()=>{setAchievement(null);navigate('home')}}>回到今日，看看进步</Button><Button variant="secondary" onClick={()=>{const id=achievement.recordId;setAchievement(null);detail(id)}}>查看这份训练证据</Button></section></div>}
  {toast&&<div className="toast" role="status"><Icon name="check" size={17}/><span>{toast.message}</span>{toast.action&&<button onClick={()=>{toast.action.run();setToast(null)}}>{toast.action.label}</button>}</div>}
  {busy&&<div className="saving-indicator" role="status">正在收好这一笔…</div>}
 </div>
}

function RecordCard({record:r,detail,openMedia,coverOf,feature=false}){const m=coverOf(r);return <article className={`record-card ${feature?'featured':''}`}><Photo src={m?.src} alt={m?.title||r.title} onClick={()=>openMedia(m?.id)} className="record-cover"/><button className="record-info" onClick={()=>detail(r.id)}><div className="record-meta"><span>{TYPE_LABEL[r.type]}</span><Status value={r.status}/></div><h3>{r.title}</h3><div className="record-tags">{r.tags?.slice(0,2).map(t=><span key={t}>{t}</span>)}</div><footer><time>{formatDate(r.date,true)} · {r.time}</time><b>{amountText(r)}</b></footer></button></article>}

function ActivityList({data,detail}){const activities=derive(data).recentActivities.slice(0,3);return <><SectionTitle title="最近的脚印" aside="与你的记录同步"/>{activities.length?<div className="activity-list">{activities.map((a,i)=><button key={a.id||i} onClick={()=>detail(a.recordId)}><i/><div><p>{a.message||a.description||a.text||a.title||'留下一份训练记录'}</p><small>{localTimestamp(a.at||a.date||a.timestamp)}</small></div><Icon name="chevron" size={17}/></button>)}</div>:<p className="help-note">第一笔写下后，脚印会留在这里。</p>}</>}

function CalendarPage({data,day,setDay,month,setMonth,actions}){const [year,mon]=month.split('-').map(Number);const first=new Date(year,mon-1,1),offset=(first.getDay()+6)%7,total=new Date(year,mon,0).getDate();const records=data.records.filter(r=>r.date===day&&r.type!=='exercise').sort(byOldest);function move(n){const d=new Date(year,mon-1+n,1);setMonth(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)}const upcoming=derive(data).nextReminders[0];return <><div className="calendar-paper"><div className="calendar-header"><h2>{year}<span>年</span> {String(mon).padStart(2,'0')}<span>月</span></h2><div><IconButton name="back" label="上个月" onClick={()=>move(-1)}/><IconButton name="chevron" label="下个月" onClick={()=>move(1)}/></div></div><div className="week-labels">{'一二三四五六日'.split('').map(x=><span key={x}>{x}</span>)}</div><div className="calendar-grid">{Array.from({length:offset},(_,i)=><span key={'blank'+i}/>)}{Array.from({length:total},(_,i)=>{const date=`${month}-${String(i+1).padStart(2,'0')}`,rs=data.records.filter(r=>r.date===date&&r.type!=='exercise');return <button key={date} className={`${date===day?'selected':''} ${date===today()?'is-today':''}`} onClick={()=>setDay(date)} aria-label={`${date}，${rs.length}条记录`}><b>{i+1}</b><span>{rs.slice(0,3).map((r,j)=><i key={j} className={r.status}/>)}</span></button>})}</div><div className="calendar-legend"><span><i/>已完成</span><span><i/>进行中</span><span><i/>待进行</span><button onClick={()=>{setDay(today());setMonth(today().slice(0,7))}}>回到今天</button></div></div>{upcoming&&<button className="reminder-strip" onClick={()=>actions.detail(upcoming.recordId)}><Icon name="bell" size={20}/><span>{upcoming.overdue?`已经过了 ${Math.abs(upcoming.days)} 天`:upcoming.days===0?'今天的提醒':`距离下一次还有 ${upcoming.days} 天`}<b>{formatDate(upcoming.date,true)} · {upcoming.title}</b></span><Icon name="chevron" size={18}/></button>}<SectionTitle title={`${formatDate(day,true)} · 日程手记`} aside={`${records.length} 条`}/><Button icon="plus" variant="outline" onClick={()=>actions.newRecord('plan',day)}>为这一天安排训练</Button><div className="timeline">{records.map(r=><div className="timeline-item" key={r.id}><div className="timeline-time"><b>{r.time}</b><i className={r.status}/></div><RecordCard record={r} {...actions}/></div>)}</div>{!records.length&&<Empty title="这一天，留白也很好" text="安排一次训练，或给恢复留一份记录。" action="为这天新增记录" onAction={()=>actions.newRecord('plan',day)}/>}</>}

function Insights({data,range,setRange,customRange,setCustomRange,actions,report}){let [from,to]=weekRange();if(range==='month'){from=today().slice(0,7)+'-01';to=today()}if(range==='custom'){from=customRange.from;to=customRange.to}const rs=data.records.filter(r=>r.date>=from&&r.date<=to),actionRows=actionable(data.records).filter(r=>r.date>=from&&r.date<=to),done=rs.filter(r=>r.status==='done'),training=done.filter(r=>r.type==='training'),bodies=done.filter(r=>r.type==='body').sort(byOldest);const days=[];let date=from;for(let i=0;date<=to&&i<366;i++,date=dateOffset(1,date))days.push(date);const displayDays=days.length>14?Array.from({length:7},(_,i)=>days[Math.round(i*(days.length-1)/6)]):days;const categories=data.categories.map(c=>({name:typeof c==='string'?c:c.name,count:rs.filter(r=>r.category===(typeof c==='string'?c:c.name)).length}));const maxCount=Math.max(1,...displayDays.map(d=>actionRows.filter(r=>r.date===d).length));const water=done.filter(r=>r.type==='water').reduce((n,r)=>n+Number(r.fields.amount||0),0);return <><div className="segmented">{[['week','本周'],['month','本月'],['custom','自定义']].map(([v,t])=><button key={v} className={range===v?'active':''} onClick={()=>setRange(v)}>{t}</button>)}</div>{range==='custom'&&<div className="field-grid range-fields"><Field label="开始日期"><input type="date" value={from} max={to} onChange={e=>setCustomRange({...customRange,from:e.target.value})}/></Field><Field label="结束日期"><input type="date" min={from} value={to} onChange={e=>setCustomRange({...customRange,to:e.target.value})}/></Field></div>}<div className="range-caption">{formatDate(from,true)} — {formatDate(to,true)}<span>来源：{rs.length} 条训练志记录</span></div>{from>to?<FormError>结束日期需要在开始日期之后。</FormError>:!rs.length?<Empty title="这个阶段，还没有留下记录" text="先记下一次训练，身体的变化就有了起点。" action="新增一笔" onAction={()=>actions.newRecord()}/>:<><div className="insight-hero"><div className="small-label">这一阶段，你举起了</div><button onClick={()=>actions.openLog({type:'training',status:'done',from,to})}><strong>{formatNumber(training.reduce((s,r)=>s+trainingVolume(r),0))}</strong><span>kg</span><Icon name="arrow" size={22}/></button><p>{training.length} 次力量训练 · {training.reduce((n,r)=>n+Number(r.fields.duration||0),0)} 分钟专注</p><div className="insight-rule"/><small>计算：已完成训练中，每个已完成组的重量 × 次数相加</small></div><SectionTitle title="坚持，开始有了形状" aside="完成趋势"/><div className="chart-paper"><div className="chart-title"><span>每日完成行动数</span><span><i className="legend-orange"/> 已完成 <i className="legend-gray"/> 总记录</span></div><div className="bar-chart">{displayDays.map(d=>{const all=actionRows.filter(r=>r.date===d),n=all.filter(r=>r.status==='done').length;return <button key={d} onClick={()=>actions.openLog({from:d,to:d,scope:'actions'})} aria-label={`${d}完成${n}条，总计${all.length}条`}><b>{n}</b><div className="bar-track" style={{height:Math.max(3,all.length/maxCount*105)}}><i style={{height:`${all.length?n/all.length*100:0}%`}}/></div><small>{d.slice(5).replace('-','/')}</small></button>})}</div><p className="source-caption">点击日期查看来源 · {days.length>14?'按均匀日期抽样展示，其余日期可在日程查看':'计划与同日执行合并，口径与今日进度一致'}</p></div><SectionTitle title="身体，把答案写下来" aside="体重 / kg"/><div className="weight-chart">{bodies.length?<><div className="weight-chart-value"><b>{bodies.at(-1).fields.weight}<small>kg</small></b><span>{bodies.length>1?`${(bodies.at(-1).fields.weight-bodies[0].fields.weight).toFixed(1)} kg / 本阶段`:'第一个体重起点'}</span></div><Sparkline values={bodies.map(r=>r.fields.weight)} width={318} height={104} labels={bodies.map(r=>r.date)} onPoint={i=>actions.detail(bodies[i].id)}/><div className="axis-labels"><span>{formatDate(bodies[0].date,true)}</span><span>{formatDate(bodies.at(-1).date,true)}</span></div><p className="source-caption">来源：{bodies.length} 次已完成体测 · 点击测量点查看</p></>:<Empty title="先给身体一个起点" text="记录晨起体重后，这里会连起真实变化。" action="记录体测" onAction={()=>actions.newRecord('body')}/>}</div><SectionTitle title="你的成长配方" aside={`${rs.length} 条记录`}/><div className="category-breakdown">{categories.map((c,i)=><button key={c.name} onClick={()=>actions.openLog({category:c.name,from,to})}><div><i style={{background:['#eb603c','#697d70','#b4a993','#202628','#939797'][i%5]}}/><span>{c.name}</span><b>{c.count}<small> 条 · {Math.round(c.count/rs.length*100)}%</small></b></div><div className="category-track"><span style={{width:`${c.count/rs.length*100}%`,background:['#eb603c','#697d70','#b4a993','#202628','#939797'][i%5]}}/></div></button>)}</div><div className="insight-advice"><Icon name="book" size={24}/><div><h3>读懂这一阶段</h3><p>{training.length?`你完成了 ${training.length} 次训练，平均每次 ${Math.round(training.reduce((n,r)=>n+Number(r.fields.duration||0),0)/training.length)} 分钟。`:'这个阶段还没有已完成的力量训练。'}{bodies.length<2?'体测少于两次，暂不判断趋势。':'体重变化只比较所选日期内的测量，不代表脂肪变化。'}先把每次训练记录完整，再观察自己的节奏。</p><button onClick={()=>actions.openLog({from,to})}>查看依据 <Icon name="arrow" size={15}/></button></div></div><div className="small-stats"><button onClick={()=>actions.openLog({status:'done',from,to})}><b>{done.length}<small>条</small></b><span>已完成记录</span></button><button onClick={()=>actions.openLog({type:'water',status:'done',from,to})}><b>{formatNumber(water)}<small>ml</small></b><span>已记录补水</span></button></div></>}<Button icon="trophy" onClick={()=>report({from,to})}>生成我的阶段报告</Button></>}

function Gallery({data,theme,setTheme,actions,upload}){const referenced=data.media.filter(m=>data.records.some(r=>r.mediaIds?.includes(m.id)||r.coverId===m.id));const media=referenced.filter(m=>theme==='all'||data.records.some(r=>r.type===theme&&(r.mediaIds?.includes(m.id)||r.coverId===m.id))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return <><div className="album-heading"><div><b>{referenced.length}</b><span>份身体成长证据</span></div><Button variant="dark" icon="upload" onClick={upload}>上传素材</Button></div><div className="chip-scroll gallery-chips">{[['all','全部档案'],['training','训练现场'],['body','身体变化'],['meal','一日餐盘'],['water','补水'],['sleep','恢复']].map(([v,t])=><button key={v} className={`chip ${theme===v?'active':''}`} onClick={()=>setTheme(v)}>{t}</button>)}</div>{!media.length?<Empty title="这里，等着你的第一张证据" text="把照片与一条记录放在一起，日后就能读懂进步。" action="上传并关联记录" onAction={upload}/>:<div className="gallery-grid">{media.map((m,i)=>{const refs=data.records.filter(r=>r.mediaIds?.includes(m.id)||r.coverId===m.id);return <article className={`gallery-item ${i%5===0?'wide':''} ${i%5===2?'portrait':''}`} key={m.id}>{m.kind==='image'||!m.kind?<Photo src={m.src} alt={m.title} onClick={()=>actions.openMedia(m.id)}/>:<button className="file-thumb" onClick={()=>actions.openMedia(m.id)}><Icon name={m.kind==='audio'?'volume':'file'} size={40}/><span>{m.title}</span></button>}<button className="gallery-caption" onClick={()=>actions.openMedia(m.id)}><h3>{m.title}</h3><p>{formatDate(refs.sort(byNewest)[0]?.date||m.date,true)} · {refs.length} 条关联记录 <Icon name="arrow" size={13}/></p></button></article>})}</div>}<p className="help-note">照片来自同一份训练志。移除记录后，专属素材也会同步移出这里。</p></>}

function Settings({data,commit,notify,exportAll,importAll}){const [name,setName]=useState(data.settings.name),[water,setWater]=useState(data.settings.waterGoal),[weekly,setWeekly]=useState(data.settings.weeklyTrainingGoal),[category,setCategory]=useState(''),[error,setError]=useState('');async function saveSettings(){if(!name.trim()||!Number.isFinite(+water)||+water<250||+water>6000||+weekly<1||+weekly>7){setError('请填写称呼；补水目标为 250–6000 ml，训练目标为每周 1–7 次。');return}setError('');await commit({...data,settings:{...data.settings,name:name.trim(),waterGoal:+water,weeklyTrainingGoal:+weekly}},'新的节奏已经记好，首页目标同步更新。',{undo:true})}async function addCategory(e){e.preventDefault();const c=category.trim();if(!c||c.length>16){setError('给分类起一个 1–16 字的名字。');return}if(data.categories.some(x=>(typeof x==='string'?x:x.name)===c)){setError('这个分类已经在了，直接使用就好。');return}if(await commit({...data,categories:[...data.categories,c]},`「${c}」已加入表单、筛选与统计。`)){setCategory('');setError('')}}return <><div className="profile-card"><Logo size={58}/><h2>{data.settings.name}</h2><p>把身体当作一项值得耐心的作品。</p><span>肌动 · 个人本地档案</span></div><SectionTitle title="我的日常目标"/><Field label="你的称呼"><input value={name} maxLength={20} onChange={e=>setName(e.target.value)}/></Field><div className="field-grid"><Field label="每日补水目标 / ml"><input type="number" min="250" max="6000" value={water} onChange={e=>setWater(e.target.value)}/></Field><Field label="每周训练 / 次"><input type="number" min="1" max="7" value={weekly} onChange={e=>setWeekly(e.target.value)}/></Field></div><FormError>{error}</FormError><Button icon="check" onClick={saveSettings}>保存我的节奏</Button><SectionTitle title="提醒方式"/><button className="setting-switch" role="switch" aria-checked={data.settings.reminders} onClick={()=>commit({...data,settings:{...data.settings,reminders:!data.settings.reminders}},data.settings.reminders?'应用内提醒已暂停。':'会按记录中的下一次日期提醒你。')}><div><b>显示下一次训练提醒</b><small>按每条记录的「下次日期」计算</small></div><span className={data.settings.reminders?'on':''}><i/></span></button><p className="help-note">提醒显示在日程内。应用关闭后，不会发送系统通知。</p><SectionTitle title="按你的习惯分类" aside={`${data.categories.length} 个`}/><div className="category-tags">{data.categories.map(c=><span key={typeof c==='string'?c:c.name}><Icon name="tag" size={13}/>{typeof c==='string'?c:c.name}</span>)}</div><form className="inline-form" onSubmit={addCategory}><input aria-label="新分类名称" placeholder="例如：户外步行" value={category} maxLength={16} onChange={e=>setCategory(e.target.value)}/><Button type="submit" variant="dark" icon="plus">添加</Button></form><SectionTitle title="训练档案，自己保管"/><div className="settings-actions"><button onClick={exportAll}><Icon name="download"/><div><b>导出完整数据</b><small>记录、媒体、分类和设置 · JSON 文件</small></div><Icon name="chevron" size={18}/></button><button onClick={importAll}><Icon name="upload"/><div><b>从备份恢复</b><small>先核对内容，再确认替换</small></div><Icon name="chevron" size={18}/></button></div><div className="local-note"><Icon name="info" size={21}/><p>你的数据只保存在当前设备的浏览器中。清理浏览器数据或更换设备不会自动迁移，请定期导出备份。照片及文件保存在本地，不会上传到服务器。</p></div><div className="seed-note">首屏为「林屿」的可编辑体验档案，全部为连贯创作的示范内容。你可以直接修改、删除，开始记录自己的身体。<br/><span>肌动 v1.0 · 390 × 844 移动工作台</span></div></>}

function Detail({record:r,data,actions,close,busy}){const media=actions.coverOf(r),fields=r.fields||{},isTraining=['training','plan'].includes(r.type);const linked=data.records.filter(x=>x.id===r.planId||x.planId===r.id||x.id===fields.sourceRecordId||x.fields?.sourceRecordId===r.id||fields.sourceIds?.includes(x.id));const sameDay=data.records.filter(x=>x.id!==r.id&&x.date===r.date&&!linked.some(y=>y.id===x.id)).slice(0,3);const events=data.activities.filter(a=>a.recordId===r.id).slice(0,6);const allSets=fields.exercises?.flatMap(e=>e.sets)||[];async function toggleSet(ei,si){const next=structuredClone(r);next.fields.exercises[ei].sets[si].done=!next.fields.exercises[ei].sets[si].done;await actions.commit(mutateRecord(data,next),'这一组已经记好，训练量已更新。',{undo:true})}const values=r.type==='body'?[['体重',fields.weight,'kg'],['体脂率',fields.fat,'%']]:r.type==='measure'?[['腰围',fields.waist,'cm'],['臀围',fields.hip,'cm'],['胸围',fields.chest,'cm']]:r.type==='meal'?[['热量',fields.calories,'kcal'],['蛋白质',fields.protein,'g'],['餐次',fields.mealType,'']]:r.type==='water'?[['本次补水',fields.amount,'ml']]:r.type==='sleep'?[['睡眠时长',fields.hours,'小时'],['恢复感受',fields.quality,'']]:r.type==='record'?[['个人纪录',fields.value,fields.unit],['成果',fields.achievement,'']]:r.type==='exercise'?[['目标肌群',fields.muscle,''],['器械',fields.equipment,'']]:[];return <Sheet title="训练志 · 这一页" subtitle={`${formatDate(r.date)} ${r.time}`} onClose={close} wide footer={<div className="detail-footer">{r.type==='plan'&&r.status!=='done'?<Button icon={r.status==='active'&&!fields.exercises?.length?'check':'play'} onClick={()=>r.status==='active'&&!fields.exercises?.length?actions.requestComplete(r):actions.startTraining(r)}>{r.status==='active'&&!fields.exercises?.length?'完成恢复计划':'开始执行计划'}</Button>:r.status!=='done'?<Button icon="check" disabled={busy} onClick={()=>actions.requestComplete(r)}>{r.type==='training'?'结束训练，留下证据':'完成这条记录'}</Button>:<Button variant="secondary" icon="undo" disabled={busy} onClick={()=>actions.changeStatus(r,'active')}>重新开启记录</Button>}<IconButton name="edit" label="编辑记录" onClick={()=>actions.edit(r)}/></div>}>
 <Photo src={media?.src} alt={media?.title||r.title} onClick={()=>actions.openMedia(media?.id)} className={`detail-cover ${r.type==='exercise'?'wide-cover':''}`}/><div className="detail-meta"><span>{TYPE_LABEL[r.type]}</span><Status value={r.status}/></div><h1 className="detail-title">{r.title}</h1><div className="detail-tags"><span>{r.category}</span>{r.tags?.map(t=><span key={t}>#{t}</span>)}</div>
 {isTraining?<><div className="training-numbers"><div><b>{formatNumber(r.type==='plan'?recordValue(r):trainingVolume(r))}<small>{recordUnit(r)}</small></b><span>{r.type==='plan'?(fields.exercises?.length?'计划训练量':'恢复时长'):'已勾选组的训练量'}</span></div><div><b>{fields.duration||0}<small>min</small></b><span>训练时长</span></div><div><b>{r.type==='plan'?allSets.length:allSets.filter(s=>s.done).length}<small>{r.type==='plan'?'组':`/${allSets.length}`}</small></b><span>{r.type==='plan'?'计划组数':'完成组数'}</span></div></div><p className="location-line"><Icon name="location" size={17}/>{fields.location||'未填写训练地点'}</p>{allSets.length>0?<SectionTitle title="把每一组，练扎实" aside={r.type==='plan'?'计划组数':'点按组号留证'}/>:<p className="help-note">这是一项恢复安排，完成后计入今日行动，不增加力量训练次数。</p>}<div className="exercise-groups">{fields.exercises?.map((e,ei)=><div className="exercise-group" key={ei}><div className="exercise-title"><span>{String(ei+1).padStart(2,'0')}</span><h3>{e.name}</h3><button onClick={()=>{const match=data.records.find(x=>x.type==='exercise'&&(x.title.includes(e.name)||e.name.includes(x.title)));match?actions.detail(match.id):actions.openLog({type:'exercise',q:e.name})}}>动作<Icon name="chevron" size={14}/></button></div><div className="set-header"><span>组</span><span>重量 / kg</span><span>次数</span><span>状态</span></div>{e.sets.map((s,si)=><button key={si} className={`training-set ${s.done?'checked':''}`} disabled={busy||r.type==='plan'} onClick={()=>toggleSet(ei,si)} aria-label={`${e.name}第${si+1}组，${s.weight}千克${s.reps}次，${s.done?'已完成':'未完成'}`}><span>{String(si+1).padStart(2,'0')}</span><b>{s.weight}</b><b>{s.reps}</b><span className="set-check">{s.done?<Icon name="check" size={17}/>:'—'}</span></button>)}</div>)}</div>{r.type==='training'&&<Button variant="dark" icon="clock" onClick={()=>actions.startTimer(r.id)}>开启组间休息计时</Button>}</>:<div className="detail-values">{values.map(([label,value,unit])=><div key={label}><span>{label}</span><b>{value??'未记录'}<small>{unit}</small></b></div>)}</div>}
 {r.type==='exercise'&&<div className="instruction-paper"><span className="small-label">动作手记 / MOVEMENT NOTES</span><p>{fields.instructions||r.notes}</p><Button icon="plus" variant="outline" onClick={()=>actions.newRecord('training',today(),{title:r.title.replace(/·.*$/,'').trim()+' · 专项训练',coverId:r.coverId,mediaIds:r.mediaIds,tags:r.tags,notes:fields.instructions||r.notes,fields:{duration:30,location:'社区训练馆',exercises:[{name:r.title.replace(/·.*$/,'').trim(),sets:[{weight:12,reps:10,done:false},{weight:12,reps:10,done:false},{weight:12,reps:10,done:false}]}]}})}>用这个动作开启训练记录</Button></div>}
 <SectionTitle title="身体的原话"/><div className="notes-paper"><Icon name="book" size={21}/><p>{r.notes||'这一页还没有备注。编辑时可以写下发力感受、餐食内容或恢复状态。'}</p></div>
 {r.nextDate&&<div className="reminder-strip"><Icon name="bell" size={18}/><span>下一次日期<b>{formatDate(r.nextDate)}</b></span><small>{Math.round((new Date(r.nextDate+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000)} 天</small></div>}
 {(r.mediaIds?.length||0)>1&&<><SectionTitle title="这一页的素材" aside={`${r.mediaIds.length} 份`}/><div className="detail-media-strip">{r.mediaIds.map(id=>{const m=data.media.find(x=>x.id===id);return m&&(m.kind==='image'||!m.kind?<Photo key={m.id} src={m.src} alt={m.title} onClick={()=>actions.openMedia(m.id)}/>:<button key={m.id} className="attachment" onClick={()=>actions.openMedia(m.id)}><Icon name={m.kind==='audio'?'volume':'file'}/><span>{m.title}</span></button>)})}</div></>}
 <SectionTitle title="关联记录" aside={linked.length?'计划与执行互相留痕':'同日身体手记'}/>{[...linked,...sameDay].length?<div className="related-list">{[...linked,...sameDay].map(x=><button key={x.id} onClick={()=>actions.detail(x.id)}><Icon name={x.type} size={21}/><div><b>{x.title}</b><small>{formatDate(x.date,true)} · {TYPE_LABEL[x.type]} · {amountText(x)}</small></div><Icon name="chevron" size={17}/></button>)}</div>:<p className="help-note">还没有相关内容。新增训练时可以选择它所属的计划。</p>}
 <SectionTitle title="这一页的脚印"/>{events.length?<div className="detail-history">{events.map((a,i)=><div key={a.id||i}><i/><span>{a.description||a.title||'记录已保存'}<small>{localTimestamp(a.at)}</small></span></div>)}</div>:<p className="help-note">原始记录已入册，之后的编辑和状态变化会留在这里。</p>}
 <div className="status-control">{r.type==='plan'&&data.records.some(x=>x.planId===r.id)&&<p className="help-note">调整计划状态会同步关联执行的状态；未勾选组不会计入实际训练量。</p>}<Field label="调整记录状态"><select value={r.status} onChange={e=>e.target.value==='done'?actions.requestComplete(r):actions.changeStatus(r,e.target.value)}><option value="planned">待进行</option><option value="active">进行中</option><option value="done">已完成</option></select></Field></div><div className="detail-utilities"><button onClick={()=>actions.edit(r)}><Icon name="edit" size={18}/>编辑这一页</button><button onClick={()=>{downloadJSON({app:'肌动',exportedAt:new Date().toISOString(),record:r,media:data.media.filter(m=>r.mediaIds?.includes(m.id)||r.coverId===m.id)},`肌动-${r.title}.json`);actions.notify('这一页已导出，连同关联的素材一起。')}}><Icon name="download" size={18}/>导出 / 分享</button></div><button className="delete-link" onClick={()=>actions.remove(r)}><Icon name="trash" size={17}/>删除这条记录</button>
 </Sheet>}

function FilterSheet({filters,data,close,apply}){const [f,setF]=useState({...filters}),[error,setError]=useState('');const tags=[...new Set(data.records.flatMap(r=>r.tags||[]))];return <Sheet title="整理训练志" subtitle="把此刻想看的那部分，翻出来。" onClose={close} footer={<><Button icon="filter" onClick={()=>{if(f.from&&f.to&&f.from>f.to){setError('开始日期不能晚于结束日期。');return}apply(f)}}>查看 {selectRecords(data,f).length} 条记录</Button><Button variant="secondary" onClick={()=>setF({...DEFAULT_FILTER})}>重置全部条件</Button></>}><Field label="记录类型"><select value={f.type} onChange={e=>setF({...f,type:e.target.value})}><option value="">全部类型</option>{Object.entries(TYPE_LABEL).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></Field><Field label="记录状态"><select value={f.status} onChange={e=>setF({...f,status:e.target.value})}><option value="">全部状态</option><option value="planned">待进行</option><option value="active">进行中</option><option value="done">已完成</option></select></Field><div className="field-grid"><Field label="开始日期"><input type="date" value={f.from} onChange={e=>setF({...f,from:e.target.value})}/></Field><Field label="结束日期"><input type="date" value={f.to} onChange={e=>setF({...f,to:e.target.value})}/></Field></div><Field label="分类"><select value={f.category} onChange={e=>setF({...f,category:e.target.value})}><option value="">全部分类</option>{data.categories.map(c=>{const name=typeof c==='string'?c:c.name;return <option key={name}>{name}</option>})}</select></Field><Field label="场景标签"><select value={f.tag} onChange={e=>setF({...f,tag:e.target.value})}><option value="">全部标签</option>{tags.map(t=><option key={t}>{t}</option>)}</select></Field><Field label="排序方式"><select value={f.sort} onChange={e=>setF({...f,sort:e.target.value})}><option value="date-desc">日期 · 最新在前</option><option value="date-asc">日期 · 最早在前</option><option value="value-desc">数值 · 从高到低</option><option value="value-asc">数值 · 从低到高</option></select></Field><p className="help-note">数值按记录主指标排序。跨类型的单位不同，选择单一类型更便于比较。</p><FormError>{error}</FormError></Sheet>}

function MediaViewer({media:m,data,close,detail,replaceCover}){const [target,setTarget]=useState(''),[replacing,setReplacing]=useState(false),[zoomed,setZoomed]=useState(false);const refs=data.records.filter(r=>r.mediaIds?.includes(m.id)||r.coverId===m.id);return <div className="media-viewer" role="dialog" aria-modal="true" aria-label={`媒体查看：${m.title}`}><header><div><span>身体成长档案</span><h2>{m.title}</h2></div><IconButton name="close" label="关闭大图" onClick={close}/></header><div className="media-viewer-scroll">{m.kind==='image'||!m.kind?<Photo src={m.src} alt={m.description||m.title} onClick={()=>setZoomed(z=>!z)} className={`full-photo ${zoomed?'zoomed':''}`}/>:m.kind==='audio'?<div className="audio-player"><Icon name="volume" size={48}/><audio src={m.src} controls/><p>{m.filename||m.title}</p></div>:<a href={m.src} download={m.filename||m.title} className="download-attachment"><Icon name="file" size={46}/>打开或下载 {m.filename||m.title}</a>}<div className="media-description"><p>{m.description||'从这条记录里，留下一份身体成长的证据。'}</p><small>{formatDate(m.date)} · {refs.length} 条关联记录</small></div><SectionTitle title="这张证据，来自这里"/>{refs.map(r=><div className="media-source" key={r.id}><button onClick={()=>detail(r.id)}><b>{r.title}</b><small>{formatDate(r.date,true)} · {amountText(r)}</small></button>{m.kind==='image'||!m.kind?<button className={r.coverId===m.id?'current-cover':''} disabled={r.coverId===m.id} onClick={()=>setTarget(r.id)}>{r.coverId===m.id?'当前封面':'设为封面'}</button>:null}</div>)}{target&&<div className="cover-confirm"><p>将「{data.records.find(r=>r.id===target)?.title}」的封面换成这张图？原图片仍保留在素材中。</p><div className="two-buttons"><Button disabled={replacing} onClick={async()=>{setReplacing(true);await replaceCover(target,m.id);setReplacing(false);setTarget('')}}>确认替换</Button><Button variant="secondary" onClick={()=>setTarget('')}>保留原封面</Button></div></div>}<Button variant="secondary" onClick={close}>收起图片，继续记录</Button></div></div>}

function Report({data,from:reportFrom,to:reportTo,actions,close,notify}){const allTraining=data.records.filter(r=>r.type==='training'&&r.status==='done');const start=reportFrom||allTraining.map(r=>r.date).sort()[0]||today(),end=reportTo||today();const s=derive(data,start,end),records=s.records.filter(r=>r.type==='training'&&r.status==='done');const achievements=(s.achievements||[]).filter(a=>a.date>=start&&a.date<=end);const report={title:`${data.settings.name}的阶段成长报告`,from:start,to:end,trainingCount:records.length,volume:records.reduce((n,r)=>n+trainingVolume(r),0),minutes:records.reduce((n,r)=>n+Number(r.fields.duration||0),0),sourceRecordIds:records.map(r=>r.id),achievements};return <Sheet title="我的阶段成长报告" subtitle={`${formatDate(start,true)} — ${formatDate(end,true)}`} onClose={close} wide footer={<><Button icon="book" onClick={async()=>{if(!report.trainingCount){actions.newRecord('training');return}const r={id:uid(),type:'record',title:`阶段总结 · ${formatDate(start,true)}—${formatDate(end,true)} 的力量印记`,date:today(),time:new Date().toTimeString().slice(0,5),status:'done',category:'个人纪录',tags:['阶段报告'],notes:`从 ${start} 到 ${end} 完成 ${report.trainingCount} 次训练，累计 ${formatNumber(report.volume)} kg 训练量，${report.minutes} 分钟专注。`,coverId:'media-hero',mediaIds:['media-hero'],fields:{value:report.trainingCount,unit:'次',achievement:'阶段力量印记',sourceIds:report.sourceRecordIds,report}};await actions.saveRecord(r)}}>{report.trainingCount?'存入我的个人纪录':'先记下一次训练'}</Button><Button variant="secondary" icon="download" onClick={()=>{downloadJSON({...report,sourceRecords:records},`肌动-阶段报告-${today()}.json`);notify('阶段报告已导出，每个数字都带着来源。')}}>导出报告与来源</Button></>}><div className="report-poster"><Logo size={41}/><span className="small-label">BODY OF EVIDENCE / {today().slice(0,4)}</span><h1>练过的，<br/>身体都记得<span>。</span></h1><div className="report-big"><b>{report.trainingCount}</b><span>次训练<br/>为自己出勤</span></div><p>{data.settings.name} · {formatDate(start,true)} — {formatDate(end,true)} 力量档案</p></div><div className="report-stats"><button onClick={()=>actions.openLog({type:'training',status:'done',from:start,to:end})}><strong>{formatNumber(report.volume)}</strong><span>kg 累计训练量 ↗</span></button><button onClick={()=>actions.openLog({type:'training',status:'done',from:start,to:end})}><strong>{report.minutes}</strong><span>分钟专注 ↗</span></button></div><SectionTitle title="你的专属印记" aside={`${achievements.length} 枚`}/>{achievements.length?achievements.map((a,i)=><button className="badge-row" key={a.id||i} onClick={()=>a.recordId?actions.detail(a.recordId):actions.openLog({type:'training',status:'done',from:start,to:end})}><span className="badge-icon"><Icon name="trophy" size={25}/></span><div><b>{a.title||a.name}</b><p>{a.description||`${a.value||''} ${a.unit||''}`}</p></div><Icon name="arrow" size={17}/></button>):<Empty title="第一枚印记，正在路上" text="完成一次真实训练，力量就有了自己的刻度。" action="去记录训练" onAction={()=>actions.newRecord('training')}/>}<SectionTitle title="每个数字，都能找到那一天"/><div className="report-sources">{records.map(r=><button key={r.id} onClick={()=>actions.detail(r.id)}><time>{formatDate(r.date,true)}</time><span>{r.title}</span><b>{formatNumber(trainingVolume(r))}<small> kg</small></b></button>)}</div><p className="help-note">报告按已完成训练实时汇总。只有已勾选的组计入训练量；这是一份个人记录，不评价健康状况。</p></Sheet>}

function UploadSheet({data,onClose,onChoose,newRecord}){const [q,setQ]=useState('');const rs=data.records.filter(r=>r.title.includes(q)).sort(byNewest);return <Sheet title="把素材放进哪一页？" subtitle="照片、录音和资料都跟着记录走，不会孤零零地散落。" onClose={onClose} footer={<Button icon="plus" onClick={newRecord}>新建记录并添加素材</Button>}><div className="search-box"><Icon name="search" size={18}/><input aria-label="搜索要上传素材的记录" placeholder="搜索关联记录" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="related-list upload-record-list">{rs.map(r=><button key={r.id} onClick={()=>onChoose(r.id)}><Icon name={r.type}/><div><b>{r.title}</b><small>{formatDate(r.date,true)} · {TYPE_LABEL[r.type]}</small></div><Icon name="chevron" size={18}/></button>)}</div>{!rs.length&&<Empty title="还没找到这一页" text="新建一条记录，再把照片一起收好。" onAction={newRecord}/>}</Sheet>}
